import{_ as e,H as s,f as t,i}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"第十五章：Claude 内置命令","description":"学会使用 Claude Code 的斜杠命令和快捷操作","frontmatter":{"title":"第十五章：Claude 内置命令","description":"学会使用 Claude Code 的斜杠命令和快捷操作"},"headers":[],"relativePath":"guide/4-advanced-usage/15-builtin-commands.md","filePath":"guide/4-advanced-usage/15-builtin-commands.md"}'),l={name:"guide/4-advanced-usage/15-builtin-commands.md"};function d(n,a,o,p,h,c){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="第十五章-claude-内置命令" tabindex="-1">第十五章：Claude 内置命令 <a class="header-anchor" href="#第十五章-claude-内置命令" aria-label="Permalink to &quot;第十五章：Claude 内置命令&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会熟练使用 Claude Code 的内置命令，提高工作效率。</p></div><h2 id="什么是内置命令" tabindex="-1">什么是内置命令 <a class="header-anchor" href="#什么是内置命令" aria-label="Permalink to &quot;什么是内置命令&quot;">​</a></h2><p>Claude Code 有一系列以 <code>/</code> 开头的内置命令（也叫斜杠命令）。输入 <code>/</code> 可以看到所有可用命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ask      /plan      /review    /test</span></span>\n<span class="line"><span>/complete /undo      /retry     /clear</span></span></code></pre></div><h2 id="常用命令详解" tabindex="-1">常用命令详解 <a class="header-anchor" href="#常用命令详解" aria-label="Permalink to &quot;常用命令详解&quot;">​</a></h2><h3 id="_1-ask-—-快速提问" tabindex="-1">1. <code>/ask</code> — 快速提问 <a class="header-anchor" href="#_1-ask-—-快速提问" aria-label="Permalink to &quot;1. `/ask` — 快速提问&quot;">​</a></h3><p>直接问一个问题，不需要在代码库上下文中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ask 什么是 TypeScript 的泛型？</span></span></code></pre></div><p><strong>使用场景：</strong></p><ul><li>快速查概念</li><li>临时问答</li><li>不需要看代码的简单问题</li></ul><h3 id="_2-plan-—-生成任务计划" tabindex="-1">2. <code>/plan</code> — 生成任务计划 <a class="header-anchor" href="#_2-plan-—-生成任务计划" aria-label="Permalink to &quot;2. `/plan` — 生成任务计划&quot;">​</a></h3><p>让 Claude 分析代码库，生成修改计划：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plan</span></span>\n<span class="line"><span>帮我重构 auth 模块，把 session 改成 JWT</span></span></code></pre></div><p>Claude 会：</p><ol><li>分析现有代码结构</li><li>生成修改步骤</li><li>等待你确认后执行</li></ol><h3 id="_3-review-—-代码审查" tabindex="-1">3. <code>/review</code> — 代码审查 <a class="header-anchor" href="#_3-review-—-代码审查" aria-label="Permalink to &quot;3. `/review` — 代码审查&quot;">​</a></h3><p>对当前分支的代码进行全面审查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span></code></pre></div><p>Claude 会：</p><ol><li>检查代码质量问题</li><li>发现潜在 bug</li><li>给出优化建议</li></ol><h3 id="_4-test-—-生成测试" tabindex="-1">4. <code>/test</code> — 生成测试 <a class="header-anchor" href="#_4-test-—-生成测试" aria-label="Permalink to &quot;4. `/test` — 生成测试&quot;">​</a></h3><p>为当前代码生成测试用例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/test</span></span>\n<span class="line"><span>帮我给这个函数写单元测试</span></span></code></pre></div><h3 id="_5-complete-—-标记完成" tabindex="-1">5. <code>/complete</code> — 标记完成 <a class="header-anchor" href="#_5-complete-—-标记完成" aria-label="Permalink to &quot;5. `/complete` — 标记完成&quot;">​</a></h3><p>标记任务完成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/complete</span></span></code></pre></div><h3 id="_6-undo-—-撤销上一步" tabindex="-1">6. <code>/undo</code> — 撤销上一步 <a class="header-anchor" href="#_6-undo-—-撤销上一步" aria-label="Permalink to &quot;6. `/undo` — 撤销上一步&quot;">​</a></h3><p>撤销 Claude 最近的操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/undo</span></span></code></pre></div><h3 id="_7-retry-—-重试" tabindex="-1">7. <code>/retry</code> — 重试 <a class="header-anchor" href="#_7-retry-—-重试" aria-label="Permalink to &quot;7. `/retry` — 重试&quot;">​</a></h3><p>让 Claude 重新思考刚才的回答：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/retry</span></span>\n<span class="line"><span>上一个方案太复杂了，换个简单的</span></span></code></pre></div><h3 id="_8-clear-—-清空对话" tabindex="-1">8. <code>/clear</code> — 清空对话 <a class="header-anchor" href="#_8-clear-—-清空对话" aria-label="Permalink to &quot;8. `/clear` — 清空对话&quot;">​</a></h3><p>清空当前对话历史：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/clear</span></span></code></pre></div><h3 id="_9-init-—-初始化项目" tabindex="-1">9. <code>/init</code> — 初始化项目 <a class="header-anchor" href="#_9-init-—-初始化项目" aria-label="Permalink to &quot;9. `/init` — 初始化项目&quot;">​</a></h3><p>在当前目录创建 Claude Code 配置文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/init</span></span></code></pre></div><h3 id="_10-claude-—-查看版本信息" tabindex="-1">10. <code>/claude</code> — 查看版本信息 <a class="header-anchor" href="#_10-claude-—-查看版本信息" aria-label="Permalink to &quot;10. `/claude` — 查看版本信息&quot;">​</a></h3><p>查看 Claude Code 版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/claude</span></span></code></pre></div><h2 id="命令行参数" tabindex="-1">命令行参数 <a class="header-anchor" href="#命令行参数" aria-label="Permalink to &quot;命令行参数&quot;">​</a></h2><p>除了斜杠命令，还可以在启动时加参数：</p><h3 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>-p, --print</code></td><td>只输出结果，不交互</td><td><code>claude -p &quot;解释这段代码&quot;</code></td></tr><tr><td><code>-c, --cached</code></td><td>使用缓存的对话</td><td><code>claude -c</code></td></tr><tr><td><code>--model</code></td><td>指定模型</td><td><code>claude --model opus</code></td></tr></tbody></table><h3 id="agent-模式" tabindex="-1">Agent 模式 <a class="header-anchor" href="#agent-模式" aria-label="Permalink to &quot;Agent 模式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude --agent</span></span></code></pre></div><p>让 Claude 自主决策和执行多步骤任务。</p><h3 id="指定项目目录" tabindex="-1">指定项目目录 <a class="header-anchor" href="#指定项目目录" aria-label="Permalink to &quot;指定项目目录&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude /path/to/project</span></span></code></pre></div><p>在指定目录启动 Claude Code。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl+C</code></td><td>中断当前操作</td></tr><tr><td><code>Ctrl+D</code></td><td>退出 Claude</td></tr><tr><td><code>Ctrl+L</code></td><td>清空屏幕</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>切换历史命令</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><h3 id="claude-api-key" tabindex="-1">CLAUDE_API_KEY <a class="header-anchor" href="#claude-api-key" aria-label="Permalink to &quot;CLAUDE_API_KEY&quot;">​</a></h3><p>设置 API Key（也可以用 <code>claude --local</code> 交互式设置）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLAUDE_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your-api-key</span></span></code></pre></div><h3 id="claude-base-url" tabindex="-1">CLAUDE_BASE_URL <a class="header-anchor" href="#claude-base-url" aria-label="Permalink to &quot;CLAUDE_BASE_URL&quot;">​</a></h3><p>使用代理或自定义端点：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLAUDE_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://your-proxy.com</span></span></code></pre></div><h3 id="claude-model" tabindex="-1">CLAUDE_MODEL <a class="header-anchor" href="#claude-model" aria-label="Permalink to &quot;CLAUDE_MODEL&quot;">​</a></h3><p>指定默认模型：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLAUDE_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opus</span></span></code></pre></div><h2 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2><p>在项目根目录创建 <code>.claude.json</code> 可以配置项目级设置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sonnet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;maxTokens&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.7</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: <code>/plan</code> 和直接说&quot;帮我改&quot;有什么区别？</strong></p><p>A: <code>/plan</code> 会先分析代码，生成详细的修改计划，等你确认后再执行。更安全，适合大改动。</p><p><strong>Q: 可以自定义斜杠命令吗？</strong></p><p>A: 可以，通过 Skill 系统可以添加自定义命令。</p><p><strong>Q: 命令行参数和配置文件哪个优先级高？</strong></p><p>A: 命令行参数 &gt; 配置文件 &gt; 默认值。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>输入 <code>/</code> 查看所有可用命令</li><li>用 <code>/ask</code> 问一个简单问题</li><li>用 <code>/review</code> 审查一段代码</li><li>尝试 <code>/undo</code> 撤销刚才的操作</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>恭喜你完成了高阶用法前三章！接下来学习 Plugin 插件系统。</p><p><a href="/guide/4-advanced-usage/16-plugin.html">👉 第十六章：Plugin 插件系统</a></p>',79)])])}const k=e(l,[["render",d]]);export{u as __pageData,k as default};
